/* Tech 3D · Nivell 1 · unitat 7 «Dissenyar per a persones» · guia del professor (m7-1 … m7-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   model en 3D (TMEDIA.model): a la pissarra digital es pot girar amb el dit o amb el ratolí. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const H = (id, t, s, p, o = {}) => P(id, t, s, p, '#9AA3B5', { hole: true, ...o });
  const RINGS = (x, d) => [20, 40, 60].map((z, i) => P('anella' + (i + 1), 'torus', [d + 4, d + 4, 4], [x, 0, z], '#5B3FD6'));
  const ACCESS = [P('prim', 'cyl', [12, 12, 80], [-30, 0, 40], '#9AA3B5'), P('gruixut', 'cyl', [30, 30, 80], [16, 0, 40], '#7C5CFF'), ...RINGS(16, 30)];
  const TOYB = [P('cos', 'box', [50, 26, 16], [0, 0, 14], '#3D7BF4'), P('cabina', 'box', [24, 22, 12], [-4, 0, 28], '#5BC0EB'), ...[[-15, -15], [15, -15], [-15, 15], [15, 15]].map(([x, y], i) => P('roda' + (i + 1), 'cyl', [14, 14, 6], [x, y, 7], '#2A2F3A', { r: [90, 0, 0] }))];
  const TOY = [...TOYB, P('punxa', 'cone', [8, 8, 18], [0, 0, 42], '#E8453C')];
  const GRIP = [P('prisma', 'hex', [24, 20.8, 40], [0, 0, 20], '#2FB36D'), H('forat', 'cyl', [8, 8, 44], [0, 0, 20])];
  const XS = [-22, 0, 22];
  const BLOC = d => [P('bloc', 'box', [70, 30, 40], [0, 0, 20], '#EC5FA8'), ...XS.map((x, i) => H('f' + (i + 1), 'cyl', [d, d, 32], [x, 0, 26]))];
  const MARK = [...BLOC(16).map(p => ({ ...p, g: 'pr' })), ...XS.flatMap((x, i) => [P('r' + (i + 1), 'cyl', [14, 14, 60], [x, 0, 40], '#F3F3EE'), P('t' + (i + 1), 'cyl', [15, 15, 20], [x, 0, 76], ['#E8453C', '#3D7BF4', '#2FB36D'][i])])];
  const STAND = y => [P('base', 'box', [80, 60, 6], [0, 0, 3], '#14A3B8'), P('topall', 'box', [80, 6, 12], [0, -27, 12], '#E8453C'), P('respatller', 'box', [80, 24, 30], [0, y, 21], '#3D7BF4')];
  const TALL = (w, x = 0, g = null) => [P('peu' + x, 'cyl', [w, w, 6], [x, 0, 3], '#F7C531', { g }), P('tub' + x, 'tube', [22, 22, 84], [x, 0, 48], '#5BC0EB', { w: 2, g })];
  const CLIPS = (h, s, x = 0, g = null) => [P('caixa' + x, 'box', [50, 50, 40], [x, 0, 20], '#FF8A3D', { g }), H('forat' + x, 'box', [s, s, h], [x, 0, 41 - h / 2], { g })];
  const SOLID = x => [P('massis', 'cyl', [50, 50, 80], [x, 0, 40], '#FF8A3D', { g: 'a' }), H('buit', 'cyl', [30, 30, 76], [x, 0, 43], { g: 'a' })];
  const TUBE = x => [P('tub', 'tube', [50, 50, 77], [x, 0, 41.5], '#2FB36D', { w: 2 }), P('fons', 'cyl', [50, 50, 3], [x, 0, 1.5], '#2FB36D')];
  const HOOK = py => [P('esquena', 'box', [12, 90, 12], [-24, 0, 6], '#7C5CFF'), P('bras', 'box', [44, 12, 12], [-2, -39, 6], '#7C5CFF'), P('punta', 'box', [12, 30, 12], [14, py, 6], '#7C5CFF'), H('c1', 'cyl', [5, 5, 14], [-24, 32, 6]), H('c2', 'cyl', [5, 5, 14], [-24, 8, 6])];
  const BOOK = [P('base', 'box', [70, 80, 5], [0, 0, 2.5], '#FF8A3D'), P('paret', 'box', [70, 5, 80], [0, -37.5, 40], '#FF8A3D'), P('reforc1', 'wedge', [30, 6, 40], [-24, -20, 25], '#E8453C', { r: [0, 0, 90] }), P('reforc2', 'wedge', [30, 6, 40], [24, -20, 25], '#E8453C', { r: [0, 0, 90] })];
  const ORG = [P('caixa', 'box', [90, 60, 40], [0, 0, 20], '#14A3B8'), H('gran', 'box', [52, 54, 38], [-16, 0, 22]), H('petit1', 'box', [26, 25, 38], [27, -14.5, 22]), H('petit2', 'box', [26, 25, 38], [27, 14.5, 22])];
  const ORG2 = [P('caixa', 'box', [60, 90, 40], [0, 0, 20], '#14A3B8'), H('gran', 'box', [54, 52, 38], [0, -16, 22]), H('petit1', 'box', [25, 26, 38], [-14.5, 27, 22]), H('petit2', 'box', [25, 26, 38], [14.5, 27, 22])];
  const mv = (l, dx, g, pre) => l.map(p => ({ ...p, id: pre + p.id, p: [p.p[0] + dx, p.p[1], p.p[2]], g }));
  const INVENTS = [...mv(HOOK(-19), -66, 'h', 'pj'), ...mv(BOOK, -2, 'b', 'al'), ...mv(ORG2, 64, 'o', 'or')];
  return {
  /* ---------- Sessió 1 · Qui ho farà servir? ---------- */
  'm7-1': {
    obj: ["L'alumne/a explica que un disseny comença per la persona que el farà servir (escoltar, imaginar, construir i provar).|El alumno/a explica que un diseño empieza por la persona que lo usará (escuchar, imaginar, construir y probar).",
      "L'alumne/a fa una entrevista breu amb preguntes obertes i n'apunta necessitats i desitjos.|El alumno/a hace una entrevista breve con preguntas abiertas y apunta necesidades y deseos.",
      "L'alumne/a reconeix idees d'accessibilitat: mànecs gruixuts, formes que es noten tocant, colors que contrasten i cap punxa.|El alumno/a reconoce ideas de accesibilidad: mangos gruesos, formas que se notan al tocar, colores que contrastan y ninguna punta.",
      "L'alumne/a modifica i construeix models senzills pensant en una necessitat concreta.|El alumno/a modifica y construye modelos sencillos pensando en una necesidad concreta."],
    comp: ["Tecnologia i digitalització: el procés de disseny centrat en les persones|Tecnología y digitalización: el proceso de diseño centrado en las personas",
      "Coneixement del medi social: empatia, diversitat i accessibilitat a la vida de cada dia|Conocimiento del medio social: empatía, diversidad y accesibilidad en la vida de cada día",
      "Comunicació oral: fer preguntes obertes, escoltar i prendre notes|Comunicación oral: hacer preguntas abiertas, escuchar y tomar notas",
      "Matemàtiques, sentit de la mesura: mides adequades al cos de les persones|Matemáticas, sentido de la medida: medidas adecuadas al cuerpo de las personas"],
    vocab: [['Disseny centrat en les persones|Diseño centrado en las personas', "Dissenyar començant per escoltar qui farà servir l'objecte.|Diseñar empezando por escuchar a quien usará el objeto."], ['Entrevista|Entrevista', 'Conversa amb preguntes per saber què necessita algú.|Conversación con preguntas para saber qué necesita alguien.'],
      ['Pregunta oberta|Pregunta abierta', 'Una pregunta que no es contesta amb un sí o un no.|Una pregunta que no se contesta con un sí o un no.'], ['Necessitat|Necesidad', "El que l'objecte ha de fer sí o sí.|Lo que el objeto tiene que hacer sí o sí."],
      ['Desig|Deseo', 'El que estaria bé que fes, però no és imprescindible.|Lo que estaría bien que hiciera, pero no es imprescindible.'], ['Accessible|Accesible', 'Que el pot fer servir tothom, també qui té poca força, poca vista o és molt petit.|Que lo puede usar todo el mundo, también quien tiene poca fuerza, poca vista o es muy pequeño.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Qui ho farà servir?»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «¿Quién lo usará?»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Llapis i la fitxa de l'entrevista, una per alumne/a|Lápices y la ficha de la entrevista, una por alumno/a"],
      imprimir: ["Fitxa de l'entrevista|Ficha de la entrevista", 'Targetes de persones|Tarjetas de personas'],
      prep: ["Imprimir la fitxa de l'entrevista i retallar les targetes de persones (per a qui no pensi en ningú).|Imprimir la ficha de la entrevista y recortar las tarjetas de personas (para quien no piense en nadie).", "Si podeu, portar dos objectes que facin la mateixa feina però siguin més o menys accessibles (una cullera prima i una de mànec gruixut, un pom i una maneta…).|Si podéis, traer dos objetos que hagan el mismo trabajo pero sean más o menos accesibles (una cuchara fina y una de mango grueso, un pomo y una manilla…).", "Provar abans el repte de l'engruixidor: cal canviar tres mides del prisma.|Probar antes el reto del engrosador: hay que cambiar tres medidas del prisma."] },
    plan: [
      { min: 5, t: 'Cartes al taller|Cartas al taller', fase: 'inici', fa: "Presenta la unitat: a partir d'ara dissenyarem per a persones concretes. Llegeix les tres cartes (l'àvia Rosa, en Pol i la Nur) i pregunta qui ha vist algú amb aquestes dificultats.|Presenta la unidad: a partir de ahora diseñaremos para personas concretas. Lee las tres cartas (la abuela Rosa, Pol y Nur) y pregunta quién ha visto a alguien con estas dificultades.",
        diu: ['Per a qui fem els objectes que dissenyem?|¿Para quién hacemos los objetos que diseñamos?', 'Quines coses de cada dia costen a algú que coneixeu?|¿Qué cosas de cada día le cuestan a alguien que conocéis?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Escoltar abans de modelar|Escuchar antes de modelar', fase: 'teoria', fa: "Explica el cercle del disseny centrat en les persones. Mostra la diferència entre preguntes obertes i tancades amb exemples en veu alta. Separa necessitats i desitjos amb el cas de l'àvia Rosa. Acaba amb l'accessibilitat girant els dos mànecs a la pissarra.|Explica el círculo del diseño centrado en las personas. Muestra la diferencia entre preguntas abiertas y cerradas con ejemplos en voz alta. Separa necesidades y deseos con el caso de la abuela Rosa. Acaba con la accesibilidad girando los dos mangos en la pizarra.",
        diu: ["Aquesta pregunta es contesta amb un sí o un no? Com la faríeu oberta?|¿Esta pregunta se contesta con un sí o un no? ¿Cómo la haríais abierta?", "És una necessitat o un desig? Què passa si no es compleix?|¿Es una necesidad o un deseo? ¿Qué pasa si no se cumple?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: "L'entrevista|La entrevista", fase: 'desconnectat', fa: "Per parelles i amb la fitxa: una persona entrevista i l'altra respon pensant en algú que conegui (o en una targeta de persona). Al cap de 5 minuts es canvien. Han d'acabar amb dues necessitats i un desig apuntats.|Por parejas y con la ficha: una persona entrevista y la otra responde pensando en alguien que conozca (o en una tarjeta de persona). A los 5 minutos se cambian. Tienen que acabar con dos necesidades y un deseo apuntados.",
        diu: ['Escolteu sense interrompre; si no enteneu alguna cosa, pregunteu «què vols dir?».|Escuchad sin interrumpir; si no entendéis algo, preguntad «¿qué quieres decir?».', "Aquesta necessitat, la podríem comprovar? Com?|Esta necesidad, ¿la podríamos comprobar? ¿Cómo?"], slides: ['s8'], app: "Encara no: la fitxa de l'entrevista.|Todavía no: la ficha de la entrevista.", org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: els encàrrecs|En el ordenador: los encargos", fase: 'ordinador', fa: "Fan la sessió a l'app: triar el pom més fàcil, trobar la punxa de la joguina i resoldre els encàrrecs (el mànec de 30 mm, l'engruixidor de llapis i l'etiqueta tàctil). Pregunta sempre per a qui és cada objecte i quina necessitat resol.|Hacen la sesión en la app: elegir el pomo más fácil, encontrar la punta del juguete y resolver los encargos (el mango de 30 mm, el engrosador de lápiz y la etiqueta táctil). Pregunta siempre para quién es cada objeto y qué necesidad resuelve.",
        diu: ["Per què l'àvia Rosa necessita 30 mm i no 12?|¿Por qué la abuela Rosa necesita 30 mm y no 12?", 'Com sabrà la Nur que és el seu penjador?|¿Cómo sabrá Nur que es su percha?'], slides: ['s9', 's10', 's11'], app: "Sessió «Qui ho farà servir?», fins a «El teu primer encàrrec».|Sesión «¿Quién lo usará?», hasta «Tu primer encargo».", org: 'Individual|Individual' },
      { min: 6, t: 'El teu primer encàrrec|Tu primer encargo', fase: 'crea', fa: "Cada alumne/a dissenya un objecte senzill per a la persona de la seva entrevista. Abans de desar-lo, ha de poder dir per a qui és i quina necessitat resol.|Cada alumno/a diseña un objeto sencillo para la persona de su entrevista. Antes de guardarlo, tiene que poder decir para quién es y qué necesidad resuelve.",
        diu: ['Per a qui és? Quina de les necessitats que vas apuntar resol?|¿Para quién es? ¿Cuál de las necesidades que apuntaste resuelve?'], slides: ['s12'], app: "Pas «El teu primer encàrrec».|Paso «Tu primer encargo».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les tres idees: escoltar primer, necessitats abans que desitjos i objectes per a tothom. Tiquet de sortida i proposta per a casa.|Repasa las tres ideas: escuchar primero, necesidades antes que deseos y objetos para todos. Ticket de salida y propuesta para casa.",
        diu: ["Digueu-me una pregunta oberta per a una entrevista.|Decidme una pregunta abierta para una entrevista."], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes de la sessió i «Com t'ha anat?».|Las últimas preguntas de la sesión y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Fa preguntes tancades («T'agradaria que fos blau?»).|Hace preguntas cerradas («¿Te gustaría que fuera azul?»).", "Proposa-li començar per «Com…?», «Què…?» o «Explica'm…». Fes-li veure que amb un sí o un no no aprèn res nou.|Propónle empezar por «¿Cómo…?», «¿Qué…?» o «Explícame…». Hazle ver que con un sí o un no no aprende nada nuevo."],
      ["Confon necessitats i desitjos (posa el color preferit com a necessitat).|Confunde necesidades y deseos (pone el color preferido como necesidad).", "Pregunta-li: si no es complís, l'objecte deixaria de servir? Si la resposta és no, és un desig.|Pregúntale: si no se cumpliera, ¿el objeto dejaría de servir? Si la respuesta es no, es un deseo."],
      ['Al mànec, escala amb «Proporcional» i el fa també més llarg.|En el mango, escala con «Proporcional» y lo hace también más largo.', "Que desactivi «Proporcional» i canviï només la X i la Y. La comprovació de 80 mm de llarg li ho recorda.|Que desactive «Proporcional» y cambie solo la X y la Y. La comprobación de 80 mm de largo se lo recuerda."],
      ["A l'engruixidor, el forat no travessa i el llapis no hi passa.|En el engrosador, el agujero no atraviesa y el lápiz no pasa.", "Que miri el model des de davant: el forat ha de ser més alt que el prisma (44 mm) i començar una mica per sota.|Que mire el modelo desde delante: el agujero tiene que ser más alto que el prisma (44 mm) y empezar un poco por debajo."]],
    diff: { mes: "Fer una segona entrevista a una persona real de l'escola (la conserge, el cuiner, un infant de P3) i proposar-li dues idees d'objecte. A l'app, afegir relleus antilliscants (anelles) al mànec.|Hacer una segunda entrevista a una persona real de la escuela (la conserje, el cocinero, un niño de P3) y proponerle dos ideas de objeto. En la app, añadir relieves antideslizantes (anillos) al mango.",
      menys: "Fer l'entrevista amb només les tres primeres preguntes de la fitxa, en veu alta i amb ajuda. A l'app, centrar-se en el mànec i l'etiqueta tàctil i fer servir la pista quan calgui.|Hacer la entrevista con solo las tres primeras preguntas de la ficha, en voz alta y con ayuda. En la app, centrarse en el mango y la etiqueta táctil y usar la pista cuando haga falta." },
    aval: { ticket: ['Digues una pregunta oberta per a una entrevista.|Di una pregunta abierta para una entrevista.', "Digues una idea per fer un objecte més accessible.|Di una idea para hacer un objeto más accesible."],
      rubric: [["L'entrevista|La entrevista", "Fa preguntes obertes, escolta i apunta dues necessitats i un desig.|Hace preguntas abiertas, escucha y apunta dos necesidades y un deseo.", "Fa sobretot preguntes de sí o no i apunta poca informació.|Hace sobre todo preguntas de sí o no y apunta poca información."],
        ['Necessitats i desitjos|Necesidades y deseos', 'Distingeix el que és imprescindible del que estaria bé.|Distingue lo que es imprescindible de lo que estaría bien.', 'Barreja necessitats i desitjos.|Mezcla necesidades y deseos.'],
        ['Accessibilitat|Accesibilidad', "Justifica les mides i les formes de l'objecte pensant en la persona.|Justifica las medidas y las formas del objeto pensando en la persona.", "Modela l'objecte, però no sap explicar per què ajuda la persona.|Modela el objeto, pero no sabe explicar por qué ayuda a la persona."]] },
    casa: "Fes una entrevista curta a algú de casa: «Quina cosa de cada dia et costa o et fa nosa?». Apunta dues necessitats i porta-les la setmana que ve: potser serà el teu proper encàrrec!|Haz una entrevista corta a alguien de casa: «¿Qué cosa de cada día te cuesta o te molesta?». Apunta dos necesidades y tráelas la semana que viene: ¡quizá será tu próximo encargo!",
    intro: "Comença la unitat més humana del curs: deixem de fer figures per fer objectes útils per a algú. L'objectiu és que l'alumnat entengui que el primer pas del disseny és escoltar, i que vegi l'accessibilitat com una manera de pensar en tothom, no com un afegit.|Empieza la unidad más humana del curso: dejamos de hacer figuras para hacer objetos útiles para alguien. El objetivo es que el alumnado entienda que el primer paso del diseño es escuchar, y que vea la accesibilidad como una manera de pensar en todos, no como un añadido.",
    claus: ['El disseny centrat en les persones comença escoltant, i es repeteix: escoltar, imaginar, construir i provar.|El diseño centrado en las personas empieza escuchando, y se repite: escuchar, imaginar, construir y probar.', 'Les preguntes obertes fan parlar; les de sí o no, no.|Las preguntas abiertas hacen hablar; las de sí o no, no.',
      'Primer es resolen les necessitats; els desitjos, si es pot.|Primero se resuelven las necesidades; los deseos, si se puede.', "Un objecte accessible pensa en qui té poca força, poca vista o és molt petit: i així és millor per a tothom.|Un objeto accesible piensa en quien tiene poca fuerza, poca vista o es muy pequeño: y así es mejor para todos."],
    prev: ['Saber canviar les mides i la posició d\'una peça amb els camps numèrics.|Saber cambiar las medidas y la posición de una pieza con los campos numéricos.', 'Saber afegir un forat i fer-lo travessar una peça (unitat 5).|Saber añadir un agujero y hacer que atraviese una pieza (unidad 5).', 'Conèixer els requisits per imprimir: tocar la placa i parets gruixudes (unitat 6).|Conocer los requisitos para imprimir: tocar la placa y paredes gruesas (unidad 6).'],
    faq: [["Com parlem de dificultats de persones concretes sense que ningú se senti assenyalat?|¿Cómo hablamos de dificultades de personas concretas sin que nadie se sienta señalado?", "Centra la conversa en les coses (la cullera és massa prima, el pom costa de girar), no en les persones. Tothom, en algun moment, té poca força o poca vista: de petits, de grans o amb un braç enguixat.|Centra la conversación en las cosas (la cuchara es demasiado fina, el pomo cuesta de girar), no en las personas. Todo el mundo, en algún momento, tiene poca fuerza o poca vista: de pequeños, de mayores o con un brazo escayolado."],
      ['Per què una maneta és més accessible que un pom?|¿Por qué una manilla es más accesible que un pomo?', "Perquè s'acciona empenyent, amb la mà oberta o el colze, sense haver de tancar els dits ni girar el canell.|Porque se acciona empujando, con la mano abierta o el codo, sin tener que cerrar los dedos ni girar la muñeca."],
      ["Els objectes que fem es podrien imprimir de debò?|¿Los objetos que hacemos se podrían imprimir de verdad?", "Sí: el mànec, l'engruixidor i l'etiqueta tàctil són peces petites i senzilles. Si teniu impressora, l'engruixidor és una bona primera prova (vigileu que el forat sigui de 8 mm o una mica més).|Sí: el mango, el engrosador y la etiqueta táctil son piezas pequeñas y sencillas. Si tenéis impresora, el engrosador es una buena primera prueba (vigilad que el agujero sea de 8 mm o un poco más)."]],
    tec: [["Al repte de l'etiqueta, el cor no es veu: queda dins la placa.|En el reto de la etiqueta, el corazón no se ve: queda dentro de la placa.", 'La z del cor ha de ser 3 (a Posició, la z és la base). Amb la vista de davant es veu de seguida.|La z del corazón tiene que ser 3 (en Posición, la z es la base). Con la vista de delante se ve enseguida.'],
      ["No es pot escriure 20,8 a la Y del prisma.|No se puede escribir 20,8 en la Y del prisma.", "Es pot escriure amb coma o amb punt. Si no, «Proporcional» des de 20 × 17,3 fins a 24 d'ample també dona 20,8.|Se puede escribir con coma o con punto. Si no, «Proporcional» desde 20 × 17,3 hasta 24 de ancho también da 20,8."],
      ["La comprovació del forat no es marca, tot i que hi ha un forat.|La comprobación del agujero no se marca, aunque hay un agujero.", "El forat ha d'estar dins de la peça i treure prou material. Toca «Resultat» per veure si talla de veritat.|El agujero tiene que estar dentro de la pieza y quitar bastante material. Toca «Resultado» para ver si corta de verdad."]],
    extra: ["Fer una «caça d'objectes accessibles» a l'escola: rampes, botons grossos, cartells amb relleu… i fotografiar-ne tres.|Hacer una «caza de objetos accesibles» en la escuela: rampas, botones grandes, carteles con relieve… y fotografiar tres.", "Provar d'escriure el nom amb guants gruixuts: què canviaria del llapis perquè fos més fàcil?|Probar a escribir el nombre con guantes gruesos: ¿qué cambiaría del lápiz para que fuera más fácil?", "Entrevistar el mateix company/a dues vegades, una amb preguntes tancades i una amb obertes, i comparar què s'aprèn.|Entrevistar al mismo compañero/a dos veces, una con preguntas cerradas y otra con abiertas, y comparar qué se aprende."],
    trans: ["Sessió següent: de l'entrevista a l'esbós amb mides i el marge dels forats.|Sesión siguiente: de la entrevista al boceto con medidas y el margen de los agujeros.", "Valors: empatia i respecte per la diversitat de les persones.|Valores: empatía y respeto por la diversidad de las personas."],
    slides: [
      { id: 's1', k: 'portada', t: 'Qui ho farà servir?|¿Quién lo usará?', x: 'Dissenyar per a persones de veritat|Diseñar para personas de verdad', nota: "Presenta la unitat i les tres cartes que han arribat al Taller de Bit.|Presenta la unidad y las tres cartas que han llegado al Taller de Bit." },
      { id: 's2', k: 'pregunta', t: "Què li costa a l'àvia Rosa?|¿Qué le cuesta a la abuela Rosa?", x: 'Té les mans rígides i li costa agafar la cullera. Què faríeu?|Tiene las manos rígidas y le cuesta coger la cuchara. ¿Qué haríais?', nota: "Recull idees sense corregir. Busquem que algú digui «preguntar-li com ho fa».|Recoge ideas sin corregir. Buscamos que alguien diga «preguntarle cómo lo hace»." },
      { id: 's3', k: 'anim', t: 'Disseny centrat en les persones|Diseño centrado en las personas', anim: 'm7pers', x: 'Escoltar, imaginar, construir i provar.|Escuchar, imaginar, construir y probar.', nota: "Insisteix que el cercle es repeteix: si la prova falla, tornem a escoltar.|Insiste en que el círculo se repite: si la prueba falla, volvemos a escuchar." },
      { id: 's4', k: 'anim', t: 'Preguntes que fan parlar|Preguntas que hacen hablar', anim: 'm7ask', x: '«Com ho fas ara?» és millor que «T\'agrada?».|«¿Cómo lo haces ahora?» es mejor que «¿Te gusta?».', nota: 'Feu entre tots tres preguntes obertes per a l\'àvia Rosa.|Haced entre todos tres preguntas abiertas para la abuela Rosa.' },
      { id: 's5', k: 'anim', t: 'Necessitats i desitjos|Necesidades y deseos', anim: 'm7need', x: 'Ha de… (sí o sí) · M\'agradaria… (si es pot)|Tiene que… (sí o sí) · Me gustaría… (si se puede)', nota: "Classifiqueu en veu alta: «que no rellisqui», «que sigui lila», «que pesi poc».|Clasificad en voz alta: «que no resbale», «que sea lila», «que pese poco»." },
      { id: 's6', k: 'media', t: 'Dos mànecs per a la mateixa cullera|Dos mangos para la misma cuchara', x: 'Quin agafaria millor algú amb poca força?|¿Cuál cogería mejor alguien con poca fuerza?', media: { k: 'model', model: { parts: ACCESS } }, nota: "Gira el model. Si heu portat objectes reals, deixeu-los provar amb guants gruixuts.|Gira el modelo. Si habéis traído objetos reales, dejad que los prueben con guantes gruesos." },
      { id: 's7', k: 'concepte', t: 'Accessibilitat: quatre idees|Accesibilidad: cuatro ideas', x: 'Mànecs gruixuts · formes que es noten tocant · colors que contrasten · cap punxa.|Mangos gruesos · formas que se notan al tocar · colores que contrastan · ninguna punta.', nota: "Demana un exemple real de cada idea (botons de l'ascensor amb relleu, retolació groga i negra…).|Pide un ejemplo real de cada idea (botones del ascensor con relieve, rotulación amarilla y negra…)." },
      { id: 's8', k: 'activitat', t: "L'entrevista|La entrevista", timer: 10, punts: ['Quina cosa de cada dia et costa?|¿Qué cosa de cada día te cuesta?', "Com ho fas ara? Ensenya-m'ho.|¿Cómo lo haces ahora? Enséñamelo.", 'Apunta 2 necessitats i 1 desig.|Apunta 2 necesidades y 1 deseo.'], nota: "Per parelles, amb la fitxa. Al cap de 5 minuts, canvi de rol.|Por parejas, con la ficha. A los 5 minutos, cambio de rol." },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["El mànec de l'àvia Rosa: 30 mm.|El mango de la abuela Rosa: 30 mm.", "L'engruixidor de llapis d'en Pol.|El engrosador de lápiz de Pol.", "L'etiqueta tàctil de la Nur.|La etiqueta táctil de Nur."], nota: "Abans de cada repte, que llegeixin per a qui és.|Antes de cada reto, que lean para quién es." },
      { id: 's10', k: 'media', t: 'La joguina de la Nil|El juguete de Nil', x: 'Quina peça podria fer mal a un infant de 3 anys?|¿Qué pieza podría hacer daño a un niño de 3 años?', media: { k: 'model', model: { parts: TOY } }, nota: "Per als qui s'encallin al repte de la punxa: la punta del con és el problema.|Para quien se atasque en el reto de la punta: la punta del cono es el problema." },
      { id: 's11', k: 'media', t: "L'engruixidor de llapis|El engrosador de lápiz", x: 'Prisma hexagonal de 24 mm amb un forat de 8 mm que el travessa.|Prisma hexagonal de 24 mm con un agujero de 8 mm que lo atraviesa.', media: { k: 'model', model: { parts: GRIP } }, nota: "Toca «Resultat» perquè vegin el forat que travessa de dalt a baix.|Toca «Resultado» para que vean el agujero que atraviesa de arriba abajo." },
      { id: 's12', k: 'repte', t: 'El teu primer encàrrec|Tu primer encargo', punts: ["Per a la persona de l'entrevista.|Para la persona de la entrevista.", 'A la mida de les seves mans.|A la medida de sus manos.', 'Sense punxes.|Sin puntas.'], nota: "No cal que sigui complicat: un objecte senzill que respongui una necessitat.|No hace falta que sea complicado: un objeto sencillo que responda a una necesidad." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['El disseny comença escoltant la persona.|El diseño empieza escuchando a la persona.', 'Primer les necessitats; després els desitjos.|Primero las necesidades; después los deseos.', 'Un objecte accessible el pot fer servir tothom.|Un objeto accesible lo puede usar todo el mundo.'], nota: 'Llegiu-ho junts en veu alta.|Leedlo juntos en voz alta.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Digues una pregunta oberta.|Di una pregunta abierta.', "Digues una idea d'accessibilitat.|Di una idea de accesibilidad."], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Entrevista algú de casa i porta dues necessitats apuntades.|Entrevista a alguien de casa y trae dos necesidades apuntadas.", nota: 'Proposta opcional: pot inspirar el projecte final.|Propuesta opcional: puede inspirar el proyecto final.' }
    ],
    print: [
      { id: 'p1', t: "Fitxa de l'entrevista|Ficha de la entrevista", k: 'fitxa', intro: "Fes l'entrevista i apunta les respostes. Després, separa necessitats i desitjos.|Haz la entrevista y apunta las respuestas. Después, separa necesidades y deseos.",
        items: [{ q: 'Per a qui dissenyo? (nom i edat aproximada)|¿Para quién diseño? (nombre y edad aproximada)', sol: 'Resposta oberta.|Respuesta abierta.' }, { q: 'Quina cosa de cada dia li costa o li fa nosa?|¿Qué cosa de cada día le cuesta o le molesta?', sol: "Una dificultat concreta (agafar, trobar, obrir, ordenar…).|Una dificultad concreta (coger, encontrar, abrir, ordenar…)." },
          { q: 'Com ho fa ara?|¿Cómo lo hace ahora?', sol: 'Descripció del que fa i on li costa.|Descripción de lo que hace y dónde le cuesta.' }, { q: 'Necessitat 1 (ha de…): ____ · Necessitat 2: ____|Necesidad 1 (tiene que…): ____ · Necesidad 2: ____', sol: "Dues coses imprescindibles, per exemple «ha de ser gruixut» i «no ha de rellisquar».|Dos cosas imprescindibles, por ejemplo «tiene que ser grueso» y «no tiene que resbalar»." },
          { q: "Desig (m'agradaria…): ____|Deseo (me gustaría…): ____", sol: "Una cosa que estaria bé, com un color o el nom.|Algo que estaría bien, como un color o el nombre." }] },
      { id: 'p2', t: 'Targetes de persones|Tarjetas de personas', k: 'targetes', intro: "Per a qui no pensi en ningú: tria una targeta i imagina que l'entrevistes.|Para quien no piense en nadie: elige una tarjeta e imagina que la entrevistas.",
        items: [{ t: "L'avi Pere, 80 anys: sempre perd les claus.|El abuelo Pere, 80 años: siempre pierde las llaves.", n: 1 }, { t: 'La Laia, 6 anys: els llapis li cauen de la taula.|Laia, 6 años: los lápices se le caen de la mesa.', n: 1 }, { t: "En Marc, braç enguixat: ha d'obrir-ho tot amb una mà.|Marc, brazo escayolado: tiene que abrirlo todo con una mano.", n: 1 },
          { t: 'La Júlia, poca vista: vol trobar el seu got a la cuina.|Júlia, poca vista: quiere encontrar su vaso en la cocina.', n: 1 }, { t: "La conserge de l'escola: les claus de les aules es barregen.|La conserje de la escuela: las llaves de las aulas se mezclan.", n: 1 }, { t: 'En Bru, 3 anys: tot s\'ho posa a la boca.|Bru, 3 años: todo se lo lleva a la boca.', n: 1 }] }
    ]
  },
  /* ---------- Sessió 2 · Esbós i mesures ---------- */
  'm7-2': {
    obj: ["L'alumne/a fa un esbós d'un objecte de davant i de dalt i hi escriu les cotes en mil·límetres.|El alumno/a hace un boceto de un objeto de delante y de arriba y escribe las cotas en milímetros.",
      "L'alumne/a mesura objectes reals amb el regle, començant pel 0 i llegint els mil·límetres.|El alumno/a mide objetos reales con la regla, empezando por el 0 y leyendo los milímetros.",
      "L'alumne/a passa les cotes de l'esbós als camps de mida i posició de l'editor.|El alumno/a pasa las cotas del boceto a los campos de medida y posición del editor.",
      "L'alumne/a aplica un marge de 2 mm als forats perquè els objectes hi càpiguen.|El alumno/a aplica un margen de 2 mm a los agujeros para que los objetos quepan."],
    comp: ['Matemàtiques, sentit de la mesura: mesurar en mm i cm i fer servir el regle amb precisió|Matemáticas, sentido de la medida: medir en mm y cm y usar la regla con precisión', 'Matemàtiques, sentit espacial: representar un objecte amb vistes (davant i dalt)|Matemáticas, sentido espacial: representar un objeto con vistas (delante y arriba)',
      'Tecnologia i digitalització: de l\'esbós al model digital|Tecnología y digitalización: del boceto al modelo digital', 'Resolució de problemes: preveure que un forat ha de deixar marge|Resolución de problemas: prever que un agujero tiene que dejar margen'],
    vocab: [['Esbós|Boceto', "Dibuix ràpid a mà per pensar com serà un objecte.|Dibujo rápido a mano para pensar cómo será un objeto."], ['Cota|Cota', "Una mida escrita al dibuix, amb una fletxa i un número.|Una medida escrita en el dibujo, con una flecha y un número."], ['Vista de davant|Vista de delante', "El dibuix de l'objecte vist de cara.|El dibujo del objeto visto de frente."],
      ['Vista de dalt|Vista de arriba', "El dibuix de l'objecte vist des de dalt.|El dibujo del objeto visto desde arriba."], ['Marge|Margen', 'Els mil·límetres de més que deixem perquè una cosa hi càpiga.|Los milímetros de más que dejamos para que una cosa quepa.'], ['Diàmetre (Ø)|Diámetro (Ø)', "L'amplada d'una cosa rodona, d'una vora a l'altra passant pel mig.|La anchura de una cosa redonda, de un borde al otro pasando por el medio."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Esbós i mesures»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Boceto y medidas»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Regles, llapis, gomes i retoladors de diferents gruixos (un lot per parella)|Reglas, lápices, gomas y rotuladores de distintos grosores (un lote por pareja)'],
      imprimir: ["Fitxa: mesura i esbossa|Ficha: mide y esboza"], prep: ["Portar retoladors de dos gruixos diferents perquè vegin que no tots fan 14 mm.|Traer rotuladores de dos grosores distintos para que vean que no todos miden 14 mm.", "Revisar que els regles comencin pel 0 (alguns tenen un tros abans).|Revisar que las reglas empiecen por el 0 (algunas tienen un trozo antes).", "Provar abans el repte dels forats amb marge: cal escriure la z = 10 a Posició.|Probar antes el reto de los agujeros con margen: hay que escribir la z = 10 en Posición."] },
    plan: [
      { min: 5, t: "L'encàrrec de la Txell|El encargo de Txell", fase: 'inici', fa: "Repassa l'entrevista i les necessitats de la sessió passada. Presenta l'encàrrec: un porta-retoladors per a l'aula de plàstica. Ensenya un retolador i pregunta quant fa de gruix.|Repasa la entrevista y las necesidades de la sesión pasada. Presenta el encargo: un portarrotuladores para el aula de plástica. Enseña un rotulador y pregunta cuánto mide de grosor.",
        diu: ['Quantes necessitats vau apuntar a casa?|¿Cuántas necesidades apuntasteis en casa?', 'Quant creieu que fa de gruix aquest retolador?|¿Cuánto creéis que mide de grosor este rotulador?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: "De l'esbós al model|Del boceto al modelo", fase: 'teoria', fa: "Dibuixa a la pissarra l'esbós del porta-retoladors de davant i de dalt, amb les cotes. Mostra com es mesura amb el regle (el 0, mirar de cara). Passa al model 3D: cada cota és un número de Mida. Acaba amb el marge: per què un forat de 14 mm no serveix.|Dibuja en la pizarra el boceto del portarrotuladores de delante y de arriba, con las cotas. Muestra cómo se mide con la regla (el 0, mirar de frente). Pasa al modelo 3D: cada cota es un número de Medida. Acaba con el margen: por qué un agujero de 14 mm no sirve.",
        diu: ["Quina cota va a la X? I a la Z?|¿Qué cota va a la X? ¿Y a la Z?", 'Si el retolador fa 14 mm, de quant fem el forat?|Si el rotulador mide 14 mm, ¿de cuánto hacemos el agujero?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Mesura i esbossa|Mide y esboza', fase: 'desconnectat', fa: "Per parelles, mesuren un llapis, una goma i un retolador i apunten les mides a la fitxa. Després cadascú fa l'esbós d'un porta-coses (de davant i de dalt) amb les cotes i els forats amb 2 mm de marge.|Por parejas, miden un lápiz, una goma y un rotulador y apuntan las medidas en la ficha. Después cada uno hace el boceto de un portacosas (de delante y de arriba) con las cotas y los agujeros con 2 mm de margen.",
        diu: ["El regle toca l'objecte pel 0?|¿La regla toca el objeto por el 0?", "Has sumat el marge als forats?|¿Has sumado el margen a los agujeros?"], slides: ['s8'], app: 'Encara no: regles i la fitxa.|Todavía no: reglas y la ficha.', org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: de les cotes als números|En el ordenador: de las cotas a los números", fase: 'ordinador', fa: "Fan la sessió a l'app: llegir mides amb la quadrícula, trobar el tub mal mesurat, fer el bloc de 70 × 30 × 40 sense fantasma, els forats amb marge i la ranura de la tauleta. Comprova que escriuen els números i no arrosseguen a ull.|Hacen la sesión en la app: leer medidas con la cuadrícula, encontrar el tubo mal medido, hacer el bloque de 70 × 30 × 40 sin fantasma, los agujeros con margen y la ranura de la tableta. Comprueba que escriben los números y no arrastran a ojo.",
        diu: ['On comença la peça per baix? Aquesta és la z de Posició.|¿Dónde empieza la pieza por abajo? Esa es la z de Posición.', "Quant fa la ranura ara? Fes servir el regle de l'app.|¿Cuánto mide la ranura ahora? Usa la regla de la app."], slides: ['s9', 's10', 's11'], app: "Sessió «Esbós i mesures», fins a «El teu porta-coses a mida».|Sesión «Boceto y medidas», hasta «Tu portacosas a medida».", org: 'Individual|Individual' },
      { min: 6, t: 'El teu porta-coses|Tu portacosas', fase: 'crea', fa: "Modelen el porta-coses del seu esbós: la peça amb les cotes i els forats amb marge. Es desa al portafoli: la sessió que ve en faran la versió 2.|Modelan el portacosas de su boceto: la pieza con las cotas y los agujeros con margen. Se guarda en el portafolio: la sesión que viene harán la versión 2.",
        diu: ["Les mides del model són les de l'esbós?|¿Las medidas del modelo son las del boceto?"], slides: ['s12'], app: "Pas «El teu porta-coses a mida».|Paso «Tu portacosas a medida».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa esbós, cotes i marge. Tiquet de sortida i proposta per a casa.|Repasa boceto, cotas y margen. Ticket de salida y propuesta para casa.",
        diu: ['Un llapis de 8 mm: de quant fem el forat?|Un lápiz de 8 mm: ¿de cuánto hacemos el agujero?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Mesura des de la vora del regle i no des del 0.|Mide desde el borde de la regla y no desde el 0.", "Fes-li posar el dit al 0 i l'objecte tocant el dit. Compareu les dues mesures.|Hazle poner el dedo en el 0 y el objeto tocando el dedo. Comparad las dos medidas."],
      ['Escriu els centímetres com si fossin mil·límetres (1,4 en lloc de 14).|Escribe los centímetros como si fueran milímetros (1,4 en lugar de 14).', "Recorda-li que al taller tot va en mil·límetres: 1 cm i 4 ratlletes són 14 mm.|Recuérdale que en el taller todo va en milímetros: 1 cm y 4 rayitas son 14 mm."],
      ["Fa els forats de la mida exacta de l'objecte.|Hace los agujeros de la medida exacta del objeto.", "Ensenya-li l'animació del marge: el retolador es queda a dalt. Suma sempre 2 mm.|Enséñale la animación del margen: el rotulador se queda arriba. Suma siempre 2 mm."],
      ['Posa la z del forat a 26 (el centre) en lloc de 10 (la base).|Pone la z del agujero en 26 (el centro) en lugar de 10 (la base).', "A Posició, la z és on comença la peça per baix. Que miri el model de davant per veure on queda el forat.|En Posición, la z es donde empieza la pieza por abajo. Que mire el modelo de delante para ver dónde queda el agujero."]],
    diff: { mes: "Fer un esbós amb tres vistes (davant, dalt i costat) i un porta-coses per a objectes de mides diferents (un forat per a cada un). Al repte extra, el porta-gomes.|Hacer un boceto con tres vistas (delante, arriba y lado) y un portacosas para objetos de medidas diferentes (un agujero para cada uno). En el reto extra, el portagomas.",
      menys: "Mesurar només el retolador i fer un esbós d'una sola vista amb dues cotes. A l'app, fer els dos primers reptes amb la pista i deixar la ranura de la tauleta per a una altra estona.|Medir solo el rotulador y hacer un boceto de una sola vista con dos cotas. En la app, hacer los dos primeros retos con la pista y dejar la ranura de la tableta para otro rato." },
    aval: { ticket: ['Un llapis fa 8 mm: de quina mida fas el forat?|Un lápiz mide 8 mm: ¿de qué medida haces el agujero?', 'Què és una cota?|¿Qué es una cota?'],
      rubric: [["L'esbós|El boceto", "Dibuixa l'objecte de davant i de dalt i hi escriu totes les cotes importants.|Dibuja el objeto de delante y de arriba y escribe todas las cotas importantes.", "Fa un dibuix, però li falten cotes o vistes.|Hace un dibujo, pero le faltan cotas o vistas."],
        ['Mesurar|Medir', 'Mesura amb el regle des del 0 i escriu el resultat en mm.|Mide con la regla desde el 0 y escribe el resultado en mm.', 'Mesura amb errors de lectura o barreja cm i mm.|Mide con errores de lectura o mezcla cm y mm.'],
        ["De l'esbós al model|Del boceto al modelo", "Passa les cotes a Mida i Posició i aplica el marge als forats.|Pasa las cotas a Medida y Posición y aplica el margen a los agujeros.", "Fa el model a ull o s'oblida del marge.|Hace el modelo a ojo o se olvida del margen."]] },
    casa: "Mesura tres objectes de casa que t'agradaria tenir ben ordenats (pintallavis, claus, piles…) i fes-ne l'esbós d'un porta-coses amb les cotes i el marge.|Mide tres objetos de casa que te gustaría tener bien ordenados (pintalabios, llaves, pilas…) y haz el boceto de un portacosas con las cotas y el margen.",
    intro: "Sessió de mesura: l'alumnat passa de la idea a un dibuix amb números i d'aquí al model. És una bona ocasió per connectar amb matemàtiques (mesura i vistes). La idea del marge és senzilla però molt potent: és la primera vegada que pensen en el món real de la impressió.|Sesión de medida: el alumnado pasa de la idea a un dibujo con números y de ahí al modelo. Es una buena ocasión para conectar con matemáticas (medida y vistas). La idea del margen es sencilla pero muy potente: es la primera vez que piensan en el mundo real de la impresión.",
    claus: ["L'esbós no ha de ser bonic: ha d'entendre's i portar les cotes.|El boceto no tiene que ser bonito: tiene que entenderse y llevar las cotas.", 'Es mesura des del 0 del regle i mirant de cara.|Se mide desde el 0 de la regla y mirando de frente.',
      'Amplada a la X, fondària a la Y, alçada a la Z.|Anchura en la X, fondo en la Y, altura en la Z.', "Forat = objecte + 2 mm de marge.|Agujero = objeto + 2 mm de margen."],
    prev: ['Saber llegir un regle en centímetres i mil·límetres (unitat 1).|Saber leer una regla en centímetros y milímetros (unidad 1).', 'Conèixer les vistes de davant i de dalt (sessió «Davant, dalt i costat»).|Conocer las vistas de delante y de arriba (sesión «Delante, arriba y lado»).', 'Saber fer forats que no travessen (unitat 5).|Saber hacer agujeros que no atraviesan (unidad 5).'],
    faq: [["Per què 2 mm de marge i no 1?|¿Por qué 2 mm de margen y no 1?", "És un valor còmode i segur per a objectes que han d'entrar i sortir fàcilment, com retoladors o llapis. Per a peces que han d'encaixar justes es fan servir marges més petits, però ho deixem per al Nivell 2.|Es un valor cómodo y seguro para objetos que tienen que entrar y salir fácilmente, como rotuladores o lápices. Para piezas que tienen que encajar justas se usan márgenes más pequeños, pero lo dejamos para el Nivel 2."],
      ["Per què els forats impresos surten més petits?|¿Por qué los agujeros impresos salen más pequeños?", "La impressora fa les vores amb un fil de plàstic que té gruix, i a les corbes interiors en posa una mica de més. Per això es dissenyen una mica més grans.|La impresora hace los bordes con un hilo de plástico que tiene grosor, y en las curvas interiores pone un poco de más. Por eso se diseñan un poco más grandes."],
      ["Cal fer sempre dues vistes?|¿Hace falta hacer siempre dos vistas?", "Per a objectes senzills, sí: la de davant dona l'alçada i la de dalt, l'amplada i la fondària. Amb aquestes dues es poden escriure totes les cotes.|Para objetos sencillos, sí: la de delante da la altura y la de arriba, la anchura y el fondo. Con estas dos se pueden escribir todas las cotas."]],
    tec: [['Al repte de la ranura, el respatller no es mou exactament on cal.|En el reto de la ranura, el respaldo no se mueve exactamente donde hace falta.', "Escriviu la y al camp de Posició (y = 0) en lloc d'arrossegar. També podeu canviar el pas de la quadrícula a 1 mm.|Escribid la y en el campo de Posición (y = 0) en lugar de arrastrar. También podéis cambiar el paso de la cuadrícula a 1 mm."],
      ["El botó del regle de l'app no mostra res.|El botón de la regla de la app no muestra nada.", "Cal tocar una peça primer: les cotes són de la peça seleccionada.|Hay que tocar una pieza primero: las cotas son de la pieza seleccionada."],
      ["Les comprovacions dels forats no es marquen tot i que es veuen bé.|Las comprobaciones de los agujeros no se marcan aunque se ven bien.", "Comproveu els tres números de Mida (16, 16, 32) i la x de cada forat (−22, 0 i 22).|Comprobad los tres números de Medida (16, 16, 32) y la x de cada agujero (−22, 0 y 22)."]],
    extra: ["Fer un «concurs d'estimació»: endevinar la mida d'objectes de l'aula i després mesurar-los.|Hacer un «concurso de estimación»: adivinar la medida de objetos del aula y después medirlos.", "Buscar plànols reals (d'un moble de muntar, d'una casa) i trobar-hi les cotes.|Buscar planos reales (de un mueble de montar, de una casa) y encontrar las cotas.", "Mesurar el gruix de tots els retoladors de la classe i fer una taula: quin forat serviria per a tots?|Medir el grosor de todos los rotuladores de la clase y hacer una tabla: ¿qué agujero serviría para todos?"],
    trans: ['Sessió següent: provar el disseny, rebre retroacció i fer la versió 2 amb menys plàstic.|Sesión siguiente: probar el diseño, recibir retroalimentación y hacer la versión 2 con menos plástico.', 'Matemàtiques: mesura de longituds i representació en vistes.|Matemáticas: medida de longitudes y representación en vistas.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Esbós i mesures|Boceto y medidas', x: 'Del paper a la pantalla amb números|Del papel a la pantalla con números', nota: "Presenta l'encàrrec de la Txell: un porta-retoladors per a l'aula de plàstica.|Presenta el encargo de Txell: un portarrotuladores para el aula de plástica." },
      { id: 's2', k: 'repas', t: "Recordem l'entrevista|Recordamos la entrevista", punts: ['Preguntes obertes|Preguntas abiertas', 'Necessitats: ha de…|Necesidades: tiene que…', "Desitjos: m'agradaria…|Deseos: me gustaría…"], nota: "Demana un parell d'exemples de les entrevistes fetes a casa.|Pide un par de ejemplos de las entrevistas hechas en casa." },
      { id: 's3', k: 'anim', t: "L'esbós|El boceto", anim: 'm7sketch', x: 'De davant i de dalt, amb les cotes.|De delante y de arriba, con las cotas.', nota: "Fes l'esbós a la pissarra alhora que l'animació. Remarca que no cal que sigui bonic.|Haz el boceto en la pizarra a la vez que la animación. Remarca que no hace falta que sea bonito." },
      { id: 's4', k: 'anim', t: 'Mesurar amb el regle|Medir con la regla', anim: 'm7ruler', x: "L'objecte toca el 0 · ratlleta = 1 mm · número = 10 mm.|El objeto toca el 0 · rayita = 1 mm · número = 10 mm.", nota: "Mesureu un retolador de veritat davant de tothom.|Medid un rotulador de verdad delante de todos." },
      { id: 's5', k: 'media', t: 'Les cotes, a l\'editor|Las cotas, en el editor', x: 'Amplada → X · fondària → Y · alçada → Z.|Anchura → X · fondo → Y · altura → Z.', media: { k: 'model', model: { parts: MARK } }, nota: "Gira el model i assenyala on hi ha cada cota: 70, 30 i 40 mm.|Gira el modelo y señala dónde está cada cota: 70, 30 y 40 mm." },
      { id: 's6', k: 'anim', t: 'El marge|El margen', anim: 'm7marge', x: 'Forat = objecte + 2 mm.|Agujero = objeto + 2 mm.', nota: "Explica que els forats impresos surten una mica més petits.|Explica que los agujeros impresos salen un poco más pequeños." },
      { id: 's7', k: 'pregunta', t: "Un llapis fa 8 mm. De quant fem el forat?|Un lápiz mide 8 mm. ¿De cuánto hacemos el agujero?", x: 'I per a una goma de 40 × 20 mm?|¿Y para una goma de 40 × 20 mm?', nota: 'Respostes: 10 mm i 42 × 22 mm.|Respuestas: 10 mm y 42 × 22 mm.' },
      { id: 's8', k: 'activitat', t: 'Mesura i esbossa|Mide y esboza', timer: 10, punts: ['Mesura un llapis, una goma i un retolador.|Mide un lápiz, una goma y un rotulador.', "Fes l'esbós d'un porta-coses.|Haz el boceto de un portacosas.", 'Escriu les cotes amb el marge.|Escribe las cotas con el margen.'], nota: "Per parelles per mesurar; l'esbós, individual.|Por parejas para medir; el boceto, individual." },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El bloc de 70 × 30 × 40 sense fantasma.|El bloque de 70 × 30 × 40 sin fantasma.', 'Tres forats de 16 mm.|Tres agujeros de 16 mm.', 'Una ranura de 12 mm.|Una ranura de 12 mm.'], nota: "Recorda que la z de Posició és la base de la peça.|Recuerda que la z de Posición es la base de la pieza." },
      { id: 's10', k: 'media', t: 'Els forats amb marge|Los agujeros con margen', x: 'Forats de 16 mm a x = −22, 0 i 22, començant a z = 10.|Agujeros de 16 mm en x = −22, 0 y 22, empezando en z = 10.', media: { k: 'model', model: { parts: BLOC(16) }, view: 'front' }, nota: "Per a qui s'encalli: es veu el fons de 10 mm sota els forats.|Para quien se atasque: se ve el fondo de 10 mm bajo los agujeros." },
      { id: 's11', k: 'media', t: 'La ranura de la tauleta|La ranura de la tableta', x: '9 mm de tauleta + 3 mm de marge = 12 mm.|9 mm de tableta + 3 mm de margen = 12 mm.', media: { k: 'model', model: { parts: STAND(0) }, view: 'right' }, nota: "Des del costat es veu bé la ranura entre el topall i el respatller.|Desde el lado se ve bien la ranura entre el tope y el respaldo." },
      { id: 's12', k: 'repte', t: 'El teu porta-coses a mida|Tu portacosas a medida', punts: ['Fet a partir del teu esbós.|Hecho a partir de tu boceto.', 'Forats amb 2 mm de marge.|Agujeros con 2 mm de margen.', 'Base plana.|Base plana.'], nota: "Desa'l: la setmana vinent en farem la versió 2.|Guárdalo: la semana que viene haremos la versión 2." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["L'esbós porta cotes en mm.|El boceto lleva cotas en mm.", 'Es mesura des del 0 del regle.|Se mide desde el 0 de la regla.', 'Forat = objecte + 2 mm.|Agujero = objeto + 2 mm.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Llapis de 8 mm: quin forat?|Lápiz de 8 mm: ¿qué agujero?', 'Què és una cota?|¿Qué es una cota?'], nota: 'Oral o amb una pissarreta.|Oral o con una pizarrita.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Mesura tres objectes de casa i fes l'esbós d'un porta-coses per a ells.|Mide tres objetos de casa y haz el boceto de un portacosas para ellos.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: mesura i esbossa|Ficha: mide y esboza', k: 'fitxa', intro: "Mesura cada objecte en mil·límetres i calcula el forat amb 2 mm de marge. Després, fes l'esbós al darrere.|Mide cada objeto en milímetros y calcula el agujero con 2 mm de margen. Después, haz el boceto detrás.",
      items: [{ q: 'Llapis: gruix ____ mm → forat ____ mm|Lápiz: grosor ____ mm → agujero ____ mm', sol: 'Per exemple, 8 mm → 10 mm.|Por ejemplo, 8 mm → 10 mm.' }, { q: 'Retolador: gruix ____ mm → forat ____ mm|Rotulador: grosor ____ mm → agujero ____ mm', sol: 'Per exemple, 14 mm → 16 mm.|Por ejemplo, 14 mm → 16 mm.' },
        { q: 'Goma: ____ × ____ mm → forat ____ × ____ mm|Goma: ____ × ____ mm → agujero ____ × ____ mm', sol: 'Per exemple, 40 × 20 mm → 42 × 22 mm.|Por ejemplo, 40 × 20 mm → 42 × 22 mm.' }, { q: "Esbós del porta-coses: vista de davant i vista de dalt, amb totes les cotes.|Boceto del portacosas: vista de delante y vista de arriba, con todas las cotas.", sol: "Dues vistes amb l'amplada, la fondària, l'alçada i el diàmetre de cada forat.|Dos vistas con la anchura, el fondo, la altura y el diámetro de cada agujero." }] }]
  },
  /* ---------- Sessió 3 · Provar i millorar ---------- */
  'm7-3': {
    obj: ["L'alumne/a explica què vol dir iterar i per què cada versió es prova amb les persones.|El alumno/a explica qué quiere decir iterar y por qué cada versión se prueba con las personas.",
      "L'alumne/a dona i rep retroacció amable i concreta amb «dues estrelles i un desig».|El alumno/a da y recibe retroalimentación amable y concreta con «dos estrellas y un deseo».",
      "L'alumne/a millora un model segons la retroacció: marge, estabilitat i menys plàstic.|El alumno/a mejora un modelo según la retroalimentación: margen, estabilidad y menos plástico.",
      "L'alumne/a buida peces deixant parets de 2-3 mm per gastar menys material.|El alumno/a vacía piezas dejando paredes de 2-3 mm para gastar menos material."],
    comp: ['Tecnologia i digitalització: avaluar i millorar prototips (iteració)|Tecnología y digitalización: evaluar y mejorar prototipos (iteración)', 'Sostenibilitat: fer servir els materials de manera responsable|Sostenibilidad: usar los materiales de manera responsable',
      'Competència personal i social: donar i rebre retroacció amb respecte|Competencia personal y social: dar y recibir retroalimentación con respeto', 'Matemàtiques: comparar volums (cm³) i àrees de la base|Matemáticas: comparar volúmenes (cm³) y áreas de la base'],
    vocab: [['Versió|Versión', "Cada una de les vegades que es fa i es millora un disseny (v1, v2…).|Cada una de las veces que se hace y se mejora un diseño (v1, v2…)."], ['Iterar|Iterar', 'Repetir el cercle de fer, provar i millorar.|Repetir el círculo de hacer, probar y mejorar.'], ['Retroacció|Retroalimentación', "El que et diuen després de provar el teu disseny: què funciona i què milloraries.|Lo que te dicen después de probar tu diseño: qué funciona y qué mejorarías."],
      ['Estable|Estable', 'Que no es tomba fàcilment.|Que no se vuelca fácilmente.'], ['Buidar|Vaciar', 'Treure el material de dins d\'una peça deixant-ne les parets.|Quitar el material de dentro de una pieza dejando sus paredes.'], ['Centímetre cúbic (cm³)|Centímetro cúbico (cm³)', "La mesura del volum: com un dau d'1 cm de costat.|La medida del volumen: como un dado de 1 cm de lado."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Provar i millorar»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Probar y mejorar»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Notes adhesives de dos colors (estrelles i desitjos) o la fitxa de retroacció|Notas adhesivas de dos colores (estrellas y deseos) o la ficha de retroalimentación'],
      imprimir: ['Fitxa: dues estrelles i un desig|Ficha: dos estrellas y un deseo'], prep: ["Tenir a mà els esbossos de la sessió passada (o que obrin el porta-coses a «Projectes»).|Tener a mano los bocetos de la sesión pasada (o que abran el portacosas en «Proyectos»).", "Si teniu una peça impresa massissa i una de buida, portar-les per comparar-ne el pes.|Si tenéis una pieza impresa maciza y una hueca, traerlas para comparar su peso.", "Provar abans el repte de la caixa de clips: cal canviar mida i posició del forat.|Probar antes el reto de la caja de clips: hay que cambiar medida y posición del agujero."] },
    plan: [
      { min: 5, t: 'Tres notes a la bústia|Tres notas en el buzón', fase: 'inici', fa: "Llegeix les tres notes de la classe de la Txell. Pregunta si són males notícies. Busquem que diguin que són pistes per millorar.|Lee las tres notas de la clase de Txell. Pregunta si son malas noticias. Buscamos que digan que son pistas para mejorar.",
        diu: ["Si el vostre disseny té un problema, vol dir que és dolent?|Si vuestro diseño tiene un problema, ¿quiere decir que es malo?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Provar, dir i millorar|Probar, decir y mejorar', fase: 'teoria', fa: "Presenta la iteració amb les versions. Modela una retroacció bona i una de dolenta en veu alta. Compara els dos porta-llapis (massís i tub) i pregunta quin gasta menys plàstic. Acaba amb l'estabilitat.|Presenta la iteración con las versiones. Modela una retroalimentación buena y una mala en voz alta. Compara los dos portalápices (macizo y tubo) y pregunta cuál gasta menos plástico. Acaba con la estabilidad.",
        diu: ["Aquesta retroacció, ajuda? Què li falta perquè ajudi?|¿Esta retroalimentación ayuda? ¿Qué le falta para que ayude?", 'Fan la mateixa feina? Quin triaríeu?|¿Hacen el mismo trabajo? ¿Cuál elegiríais?'], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Dues estrelles i un desig|Dos estrellas y un deseo', fase: 'desconnectat', fa: "Per parelles, intercanvien l'esbós o el porta-coses de la sessió passada i escriuen dues estrelles i un desig a la fitxa (o en notes adhesives). Després es tornen els papers i cadascú tria la millora que farà.|Por parejas, intercambian el boceto o el portacosas de la sesión pasada y escriben dos estrellas y un deseo en la ficha (o en notas adhesivas). Después se devuelven los papeles y cada uno elige la mejora que hará.",
        diu: ['El desig diu com millorar-ho? Amb números?|¿El deseo dice cómo mejorarlo? ¿Con números?', 'Parla del disseny, no de la persona.|Habla del diseño, no de la persona.'], slides: ['s7'], app: 'Encara no: la fitxa de retroacció.|Todavía no: la ficha de retroalimentación.', org: 'Per parelles|Por parejas' },
      { min: 22, t: "A l'ordinador: les versions 2|En el ordenador: las versiones 2", fase: 'ordinador', fa: "Fan la sessió a l'app: comparar el plàstic de dos dissenys, entendre per què es tomba el porta-raspalls i resoldre les tres notes (forats de 16 mm, base de 60 mm i caixa de clips buidada). Fixa't que llegeixin el volum a les comprovacions.|Hacen la sesión en la app: comparar el plástico de dos diseños, entender por qué se vuelca el portacepillos y resolver las tres notas (agujeros de 16 mm, base de 60 mm y caja de clips vaciada). Fíjate en que lean el volumen en las comprobaciones.",
        diu: ['Quant plàstic gastava abans? I ara?|¿Cuánto plástico gastaba antes? ¿Y ahora?', 'Si el buides del tot, què passa amb les parets?|Si lo vacías del todo, ¿qué pasa con las paredes?'], slides: ['s8', 's9', 's10'], app: "Sessió «Provar i millorar», fins a «La versió 2».|Sesión «Probar y mejorar», hasta «La versión 2».", org: 'Individual|Individual' },
      { min: 6, t: 'La versió 2|La versión 2', fase: 'crea', fa: "L'app obre el porta-coses que van desar la setmana passada (o el de la Txell). Hi apliquen la millora que van triar amb la retroacció i el desen com a versió 2.|La app abre el portacosas que guardaron la semana pasada (o el de Txell). Aplican la mejora que eligieron con la retroalimentación y lo guardan como versión 2.",
        diu: ['Quina millora has fet? Qui te la va proposar?|¿Qué mejora has hecho? ¿Quién te la propuso?'], slides: ['s11'], app: "Pas «La versió 2».|Paso «La versión 2».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa iterar, retroacció i menys plàstic. Tiquet de sortida i proposta per a casa.|Repasa iterar, retroalimentación y menos plástico. Ticket de salida y propuesta para casa.",
        diu: ['Digueu-me una manera de gastar menys plàstic.|Decidme una manera de gastar menos plástico.'], slides: ['s12', 's13', 's14'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Rep la retroacció com una crítica i no vol canviar res.|Recibe la retroalimentación como una crítica y no quiere cambiar nada.", "Recorda-li que el disseny no és la persona i que tots els dissenyadors fan versions. Ell o ella decideix quins canvis fa.|Recuérdale que el diseño no es la persona y que todos los diseñadores hacen versiones. Él o ella decide qué cambios hace."],
      ["Escriu desitjos generals («fes-lo millor»).|Escribe deseos generales («hazlo mejor»).", "Demana-li: què canviaries exactament? Quant? Per exemple: «el forat, 2 mm més gran».|Pídele: ¿qué cambiarías exactamente? ¿Cuánto? Por ejemplo: «el agujero, 2 mm más grande»."],
      ['Buida tant la caixa de clips que la travessa i queda sense fons.|Vacía tanto la caja de clips que la atraviesa y queda sin fondo.', "Que miri el model de davant: el forat ha de començar a z = 3 per deixar el fons de 3 mm.|Que mire el modelo de delante: el agujero tiene que empezar en z = 3 para dejar el fondo de 3 mm."],
      ['Per fer més estable el porta-raspalls, escurça el tub.|Para hacer más estable el portacepillos, acorta el tubo.', "També funciona, però el raspall no hi cabria. Pregunta-li què ha de mesurar el tub per al raspall i que eixampli la base.|También funciona, pero el cepillo no cabría. Pregúntale qué tiene que medir el tubo para el cepillo y que ensanche la base."]],
    diff: { mes: "Fer una versió 3 del porta-coses amb dues millores i comparar el volum de les tres versions. Al repte extra, el porta-llapis amb tub.|Hacer una versión 3 del portacosas con dos mejoras y comparar el volumen de las tres versiones. En el reto extra, el portalápices con tubo.",
      menys: "Escriure només una estrella i un desig, amb frases d'inici a la fitxa. A l'app, fer els dos primers reptes i la versió 2 amb una sola millora.|Escribir solo una estrella y un deseo, con frases de inicio en la ficha. En la app, hacer los dos primeros retos y la versión 2 con una sola mejora." },
    aval: { ticket: ['Què vol dir iterar?|¿Qué quiere decir iterar?', 'Digues una manera de gastar menys plàstic.|Di una manera de gastar menos plástico.'],
      rubric: [['Retroacció|Retroalimentación', 'Dona dues estrelles i un desig concrets i amables.|Da dos estrellas y un deseo concretos y amables.', 'Dona opinions generals («està bé», «és lleig»).|Da opiniones generales («está bien», «es feo»).'],
        ['Iterar|Iterar', 'Aplica almenys una millora de la retroacció a la versió 2.|Aplica al menos una mejora de la retroalimentación a la versión 2.', 'Fa canvis, però no tenen relació amb la retroacció.|Hace cambios, pero no tienen relación con la retroalimentación.'],
        ['Menys plàstic|Menos plástico', 'Buida les peces deixant parets de 2-3 mm i redueix el volum.|Vacía las piezas dejando paredes de 2-3 mm y reduce el volumen.', 'Buida massa (parets fines o sense fons) o no buida.|Vacía demasiado (paredes finas o sin fondo) o no vacía.']] },
    casa: "Busca a casa un objecte de plàstic que es podria haver fet amb menys material (més prim, buit o més petit) i explica com el milloraries.|Busca en casa un objeto de plástico que se podría haber hecho con menos material (más fino, hueco o más pequeño) y explica cómo lo mejorarías.",
    intro: "Sessió per normalitzar l'error: un disseny que falla és un disseny que ens dona pistes. L'alumnat practica la retroacció amable i concreta, i aprèn que gastar menys plàstic també és dissenyar bé.|Sesión para normalizar el error: un diseño que falla es un diseño que nos da pistas. El alumnado practica la retroalimentación amable y concreta, y aprende que gastar menos plástico también es diseñar bien.",
    claus: ["Cap disseny surt bé a la primera: es fan versions i es proven.|Ningún diseño sale bien a la primera: se hacen versiones y se prueban.", 'La retroacció parla del disseny, és amable i diu com millorar.|La retroalimentación habla del diseño, es amable y dice cómo mejorar.',
      'Base ampla o objecte baix: estable.|Base ancha u objeto bajo: estable.', "Buidar amb parets de 2-3 mm estalvia molt de plàstic sense que la peça es trenqui.|Vaciar con paredes de 2-3 mm ahorra mucho plástico sin que la pieza se rompa."],
    prev: ["Haver desat el porta-coses de la sessió «Esbós i mesures» (si no, l'app en dona un).|Haber guardado el portacosas de la sesión «Boceto y medidas» (si no, la app da uno).", 'Saber buidar una peça amb un forat (unitat 5).|Saber vaciar una pieza con un agujero (unidad 5).', 'Conèixer el gruix mínim de paret per imprimir (unitat 6).|Conocer el grosor mínimo de pared para imprimir (unidad 6).'],
    faq: [["D'on surten els cm³ de les comprovacions?|¿De dónde salen los cm³ de las comprobaciones?", "L'app calcula el volum del model final, amb els forats ja restats. És el plàstic que faria servir la impressora si la peça fos massissa per dins.|La app calcula el volumen del modelo final, con los agujeros ya restados. Es el plástico que usaría la impresora si la pieza fuera maciza por dentro."],
      ['Les impressores no buiden ja les peces per dins?|¿Las impresoras no vacían ya las piezas por dentro?', "Sí: el programa que prepara la impressió omple l'interior amb un reticle (el farciment). Però si nosaltres ja hem buidat la peça, estalviem encara més plàstic i temps.|Sí: el programa que prepara la impresión rellena el interior con una retícula (el relleno). Pero si nosotros ya hemos vaciado la pieza, ahorramos aún más plástico y tiempo."],
      ['Què fem si un alumne/a no va desar el porta-coses?|¿Qué hacemos si un alumno/a no guardó el portacosas?', "L'app li obre el porta-retoladors de la Txell (versió 1, amb forats de 14 mm): pot fer-ne la versió 2 igualment.|La app le abre el portarrotuladores de Txell (versión 1, con agujeros de 14 mm): puede hacer la versión 2 igualmente."]],
    tec: [['A la caixa de clips, la comprovació de les parets no es marca.|En la caja de clips, la comprobación de las paredes no se marca.', "El forat ha de ser de 44 × 44 mm i estar centrat (x = 0, y = 0): si es desplaça, una paret queda massa fina.|El agujero tiene que ser de 44 × 44 mm y estar centrado (x = 0, y = 0): si se desplaza, una pared queda demasiado fina."],
      ["A la versió 2 no apareix el seu porta-coses.|En la versión 2 no aparece su portacosas.", "Surt l'últim projecte desat a «Esbós i mesures» o a «Provar i millorar». Si es va desar amb un altre perfil, no hi serà.|Sale el último proyecto guardado en «Boceto y medidas» o en «Probar y mejorar». Si se guardó con otro perfil, no estará."],
      ["El tub del repte extra no té fons.|El tubo del reto extra no tiene fondo.", "És normal: el tub és obert. Cal afegir un cilindre de 3 mm a sota com a fons.|Es normal: el tubo es abierto. Hay que añadir un cilindro de 3 mm debajo como fondo."]],
    extra: ["Pesar dues peces impreses (una massissa i una buida) amb una balança de cuina i comparar-les.|Pesar dos piezas impresas (una maciza y una hueca) con una balanza de cocina y compararlas.", "Fer un mural «De la v1 a la v3» amb les miniatures de les versions de cada alumne/a.|Hacer un mural «De la v1 a la v3» con las miniaturas de las versiones de cada alumno/a.", "Investigar què és el PLA (el plàstic de les impressores) i com es recicla.|Investigar qué es el PLA (el plástico de las impresoras) y cómo se recicla."],
    trans: ["Sessió següent: el projecte de la unitat, un invent per a l'escola amb especificacions pròpies.|Sesión siguiente: el proyecto de la unidad, un invento para la escuela con especificaciones propias.", 'Sostenibilitat: reduir, reutilitzar i reciclar.|Sostenibilidad: reducir, reutilizar y reciclar.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Provar i millorar|Probar y mejorar', x: 'Versió 1, versió 2, versió 3…|Versión 1, versión 2, versión 3…', nota: "Presenta les tres notes que han arribat al taller.|Presenta las tres notas que han llegado al taller." },
      { id: 's2', k: 'concepte', t: 'Tres notes a la bústia|Tres notas en el buzón', x: "«Els retoladors hi entren justos» · «El porta-raspalls es tomba» · «Quant de plàstic!»|«Los rotuladores entran justos» · «El portacepillos se vuelca» · «¡Cuánto plástico!»", nota: "Pregunta: és una mala notícia? Busquem: són pistes per millorar.|Pregunta: ¿es una mala noticia? Buscamos: son pistas para mejorar." },
      { id: 's3', k: 'anim', t: 'Iterar|Iterar', anim: 'm7iter', x: 'Fer, provar i millorar, una i altra vegada.|Hacer, probar y mejorar, una y otra vez.', nota: "Explica que les grans empreses també fan desenes de versions.|Explica que las grandes empresas también hacen decenas de versiones." },
      { id: 's4', k: 'anim', t: 'Dues estrelles i un desig|Dos estrellas y un deseo', anim: 'm7feed', x: 'Amable, concreta i que digui com millorar.|Amable, concreta y que diga cómo mejorar.', nota: "Modela una retroacció dolenta («és lleig») i transformeu-la entre tots en una de bona.|Modela una retroalimentación mala («es feo») y transformadla entre todos en una buena." },
      { id: 's5', k: 'media', t: 'Menys plàstic|Menos plástico', x: 'Massís: uns 103 cm³ · Tub amb fons: uns 29 cm³.|Macizo: unos 103 cm³ · Tubo con fondo: unos 29 cm³.', media: { k: 'model', model: { parts: [...SOLID(-35), ...TUBE(35)] } }, nota: "Gira els dos porta-llapis. Fan la mateixa feina amb menys d'un terç del plàstic.|Gira los dos portalápices. Hacen el mismo trabajo con menos de un tercio del plástico." },
      { id: 's6', k: 'anim', t: 'Estable|Estable', anim: 'm7stable', x: 'Base ampla o objecte baix: no es tomba.|Base ancha u objeto bajo: no se vuelca.', nota: "Feu la prova amb un llibre dret i un d'estirat.|Haced la prueba con un libro de pie y uno tumbado." },
      { id: 's7', k: 'activitat', t: 'Dues estrelles i un desig|Dos estrellas y un deseo', timer: 8, punts: ["Intercanvia l'esbós amb un company/a.|Intercambia el boceto con un compañero/a.", 'Escriu dues estrelles i un desig.|Escribe dos estrellas y un deseo.', 'Tria la millora que faràs.|Elige la mejora que harás.'], nota: "Per parelles. Insisteix en els desitjos concrets, amb números.|Por parejas. Insiste en los deseos concretos, con números." },
      { id: 's8', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Forats de 16 mm.|Agujeros de 16 mm.', 'Una base de 60 mm.|Una base de 60 mm.', 'La caixa de clips buidada.|La caja de clips vaciada.'], nota: "Cada repte respon una de les tres notes.|Cada reto responde a una de las tres notas." },
      { id: 's9', k: 'media', t: 'El porta-raspalls, abans i després|El portacepillos, antes y después', x: 'Base de 24 mm → base de 60 mm.|Base de 24 mm → base de 60 mm.', media: { k: 'model', model: { parts: [...TALL(24, -40), ...TALL(60, 40)] }, view: 'front' }, nota: "Pregunta quin es tombaria primer si el toquéssim.|Pregunta cuál se volcaría primero si lo tocáramos." },
      { id: 's10', k: 'media', t: 'La caixa de clips buidada|La caja de clips vaciada', x: 'De 82 cm³ a uns 29 cm³, amb parets de 3 mm.|De 82 cm³ a unos 29 cm³, con paredes de 3 mm.', media: { k: 'model', model: { parts: [...CLIPS(11, 40, -40, 'a'), ...CLIPS(38, 44, 40, 'b')] } }, nota: "Toca «Resultat» per veure com queda per dins la versió buidada.|Toca «Resultado» para ver cómo queda por dentro la versión vaciada." },
      { id: 's11', k: 'repte', t: 'La versió 2|La versión 2', punts: ["S'obre el teu porta-coses.|Se abre tu portacosas.", 'Fes-hi la millora triada.|Hazle la mejora elegida.', 'Desa-la com a versió 2.|Guárdala como versión 2.'], nota: "Si algú no el va desar, l'app li dona el de la Txell.|Si alguien no lo guardó, la app le da el de Txell." },
      { id: 's12', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Iterar: fer versions i provar-les.|Iterar: hacer versiones y probarlas.', 'Retroacció: dues estrelles i un desig.|Retroalimentación: dos estrellas y un deseo.', 'Menys plàstic: buidar amb parets de 2-3 mm.|Menos plástico: vaciar con paredes de 2-3 mm.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's13', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què vol dir iterar?|¿Qué quiere decir iterar?', 'Com gastes menys plàstic?|¿Cómo gastas menos plástico?'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's14', k: 'concepte', t: 'A casa|En casa', x: "Troba un objecte de plàstic que es podria fer amb menys material i explica com.|Encuentra un objeto de plástico que se podría hacer con menos material y explica cómo.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: dues estrelles i un desig|Ficha: dos estrellas y un deseo', k: 'fitxa', intro: "Mira el disseny del teu company/a i omple la fitxa. Parla del disseny, no de la persona.|Mira el diseño de tu compañero/a y rellena la ficha. Habla del diseño, no de la persona.",
      items: [{ q: "Disseny de: ____ · Per a qui és: ____|Diseño de: ____ · Para quién es: ____", sol: 'Resposta oberta.|Respuesta abierta.' }, { q: '⭐ Estrella 1: una cosa que funciona bé.|⭐ Estrella 1: algo que funciona bien.', sol: 'Una qualitat concreta (la base és estable, els forats tenen marge…).|Una cualidad concreta (la base es estable, los agujeros tienen margen…).' },
        { q: '⭐ Estrella 2: una altra cosa que funciona bé.|⭐ Estrella 2: otra cosa que funciona bien.', sol: 'Una altra qualitat concreta.|Otra cualidad concreta.' }, { q: '💬 Desig: una millora concreta (amb números si pots).|💬 Deseo: una mejora concreta (con números si puedes).', sol: 'Per exemple: «fes la base 20 mm més ampla».|Por ejemplo: «haz la base 20 mm más ancha».' },
        { q: "Resposta de l'autor/a: quina millora faré a la versió 2?|Respuesta del autor/a: ¿qué mejora haré en la versión 2?", sol: 'Resposta oberta.|Respuesta abierta.' }] }]
  },
  /* ---------- Sessió 4 · Projecte: un invent per a l'escola ---------- */
  'm7-4': {
    obj: ["L'alumne/a escriu les especificacions d'un invent (per a qui, què fa, mides i impressió) abans de modelar-lo.|El alumno/a escribe las especificaciones de un invento (para quién, qué hace, medidas e impresión) antes de modelarlo.",
      "L'alumne/a distingeix especificacions que es poden comprovar de les que no.|El alumno/a distingue especificaciones que se pueden comprobar de las que no.",
      "L'alumne/a construeix objectes útils combinant caixes, falques i forats, pensant com s'imprimiran.|El alumno/a construye objetos útiles combinando cajas, cuñas y agujeros, pensando cómo se imprimirán.",
      "L'alumne/a modela el seu propi invent i comprova que compleix la seva fitxa.|El alumno/a modela su propio invento y comprueba que cumple su ficha."],
    comp: ['Tecnologia i digitalització: projecte tecnològic amb especificacions|Tecnología y digitalización: proyecto tecnológico con especificaciones', 'Matemàtiques, sentit espacial: composició de cossos i orientació a la placa|Matemáticas, sentido espacial: composición de cuerpos y orientación en la placa',
      "Matemàtiques, sentit de la mesura: mides màximes i comprovació|Matemáticas, sentido de la medida: medidas máximas y comprobación", "Competència ciutadana: millorar l'entorn de l'escola|Competencia ciudadana: mejorar el entorno de la escuela"],
    vocab: [['Especificació|Especificación', "Una cosa que ha de complir el disseny i que es pot comprovar.|Algo que tiene que cumplir el diseño y que se puede comprobar."], ['Invent|Invento', "Un objecte nou que resol un problema.|Un objeto nuevo que resuelve un problema."], ['Reforç|Refuerzo', "Una peça que fa més fort un objecte (com el triangle de l'aguantallibres).|Una pieza que hace más fuerte un objeto (como el triángulo del sujetalibros)."],
      ['Compartiment|Compartimento', "Cada un dels espais separats d'un organitzador.|Cada uno de los espacios separados de un organizador."], ['Orientació a la placa|Orientación en la placa', "Com es col·loca la peça per imprimir-la (estirada, dreta…).|Cómo se coloca la pieza para imprimirla (tumbada, de pie…)."], ['Suport|Soporte', "Material que la impressora afegeix sota les parts que queden a l'aire i que després es treu.|Material que la impresora añade bajo las partes que quedan en el aire y que después se quita."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: un invent per a l'escola»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: un invento para la escuela»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Regles, la fitxa d'especificacions i, si podeu, una motxilla, un llibre i un estoig per mesurar|Reglas, la ficha de especificaciones y, si podéis, una mochila, un libro y un estuche para medir"],
      imprimir: ["Fitxa d'especificacions de l'invent|Ficha de especificaciones del invento"], prep: ["Preparar a l'aula objectes reals per mesurar: la nansa d'una motxilla, un llibre de la biblioteca, clips i gomes.|Preparar en el aula objetos reales para medir: el asa de una mochila, un libro de la biblioteca, clips y gomas.", "Si podeu, convidar algú de l'escola (la directora, la bibliotecària) a escoltar les presentacions finals.|Si podéis, invitar a alguien de la escuela (la directora, la bibliotecaria) a escuchar las presentaciones finales.", "Provar abans el repte de l'aguantallibres: cal girar les falques 90° en z.|Probar antes el reto del sujetalibros: hay que girar las cuñas 90° en z."] },
    plan: [
      { min: 5, t: "El concurs d'invents|El concurso de inventos", fase: 'inici', fa: "Presenta el concurs de la Montse i els tres invents que necessita l'escola. Pregunta quins altres objectes faltarien a l'escola.|Presenta el concurso de Montse y los tres inventos que necesita la escuela. Pregunta qué otros objetos faltarían en la escuela.",
        diu: ["Què es perd, cau o està desordenat a la nostra escola?|¿Qué se pierde, cae o está desordenado en nuestra escuela?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Les especificacions|Las especificaciones', fase: 'teoria', fa: "Explica què són les especificacions i que s'han de poder comprovar. Mostra els tres invents en 3D i explica per què el penjador s'imprimeix estirat. Recorda el camí complet del disseny.|Explica qué son las especificaciones y que se tienen que poder comprobar. Muestra los tres inventos en 3D y explica por qué el colgador se imprime tumbado. Recuerda el camino completo del diseño.",
        diu: ["«Ha de ser bonic»: es pot comprovar? Com ho diríeu perquè es pogués comprovar?|«Tiene que ser bonito»: ¿se puede comprobar? ¿Cómo lo diríais para que se pudiera comprobar?", "Per què el ganxo és més fort estirat?|¿Por qué el gancho es más fuerte tumbado?"], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "La fitxa d'especificacions|La ficha de especificaciones", fase: 'desconnectat', fa: "Cada alumne/a tria el seu invent i omple la fitxa: per a qui, què fa, mides (mesurant objectes reals) i un esbós amb cotes. Passa per les taules per ajudar a fer especificacions comprovables.|Cada alumno/a elige su invento y rellena la ficha: para quién, qué hace, medidas (midiendo objetos reales) y un boceto con cotas. Pasa por las mesas para ayudar a hacer especificaciones comprobables.",
        diu: ['Has mesurat la nansa (o el llibre) de veritat?|¿Has medido el asa (o el libro) de verdad?', 'Aquesta especificació, com la comprovarem?|Esta especificación, ¿cómo la comprobaremos?'], slides: ['s7'], app: "Encara no: la fitxa d'especificacions.|Todavía no: la ficha de especificaciones.", org: 'Individual|Individual' },
      { min: 17, t: "A l'ordinador: tres invents|En el ordenador: tres inventos", fase: 'ordinador', fa: "Fan la sessió a l'app: compten compartiments, arreglen el ganxo separat i construeixen el penjador, l'aguantallibres i l'organitzador amb fantasma. Aquests tres reptes els serveixen de model per al seu invent.|Hacen la sesión en la app: cuentan compartimentos, arreglan el gancho separado y construyen el colgador, el sujetalibros y el organizador con fantasma. Estos tres retos les sirven de modelo para su invento.",
        diu: ['Quina falca has de girar i quant?|¿Qué cuña tienes que girar y cuánto?', 'Les parets fan 3 mm o més?|¿Las paredes miden 3 mm o más?'], slides: ['s8', 's9', 's10'], app: "Sessió «Projecte: un invent per a l'escola», fins a «El teu invent per a l'escola».|Sesión «Proyecto: un invento para la escuela», hasta «Tu invento para la escuela».", org: 'Individual|Individual' },
      { min: 12, t: 'El teu invent|Tu invento', fase: 'crea', fa: "Modelen l'invent de la seva fitxa. Abans de desar-lo, repassen cada especificació amb el regle de l'app i ho marquen a la fitxa.|Modelan el invento de su ficha. Antes de guardarlo, repasan cada especificación con la regla de la app y lo marcan en la ficha.",
        diu: ['Quina especificació et falta per complir?|¿Qué especificación te falta por cumplir?', 'Com el posaràs a la placa?|¿Cómo lo pondrás en la placa?'], slides: ['s11', 's12'], app: "Pas «El teu invent per a l'escola».|Paso «Tu invento para la escuela».", org: 'Individual|Individual' },
      { min: 6, t: "La galeria d'invents|La galería de inventos", fase: 'tancament', fa: "Tres o quatre alumnes ensenyen l'invent al projector i diuen per a qui és i una especificació que compleix. Tiquet de sortida.|Tres o cuatro alumnos enseñan el invento en el proyector y dicen para quién es y una especificación que cumple. Ticket de salida.",
        diu: ['Per a qui és el teu invent? Quina especificació compleix?|¿Para quién es tu invento? ¿Qué especificación cumple?'], slides: ['s13', 's14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Escriu especificacions que no es poden comprovar («que sigui xulo»).|Escribe especificaciones que no se pueden comprobar («que sea chulo»).", "Pregunta-li com sabria si s'ha complert. Ajuda'l a transformar-la en una mida o una acció: «aguanta 3 llibres», «fa com a molt 100 mm».|Pregúntale cómo sabría si se ha cumplido. Ayúdale a transformarla en una medida o una acción: «aguanta 3 libros», «mide como mucho 100 mm»."],
      ["Gira les falques de l'aguantallibres en x o y en lloc de z.|Gira las cuñas del sujetalibros en x o y en lugar de z.", "Que miri el model des de dalt: la falca ha de quedar de llarg cap al fons. El gir és a l'eix Z, 90°.|Que mire el modelo desde arriba: la cuña tiene que quedar a lo largo hacia el fondo. El giro es en el eje Z, 90°."],
      ["Dissenya el penjador dret i el ganxo queda a l'aire.|Diseña el colgador de pie y el gancho queda en el aire.", "Recorda-li la diapositiva del penjador estirat: tot el perfil a la placa, amb 12 mm de gruix.|Recuérdale la diapositiva del colgador tumbado: todo el perfil en la placa, con 12 mm de grosor."],
      ["A l'organitzador, els forats se superposen i desapareix la paret del mig.|En el organizador, los agujeros se superponen y desaparece la pared del medio.", "Que comprovi les x i les y dels forats amb la pista: entre forat i forat hi ha d'haver 4 mm de paret.|Que compruebe las x y las y de los agujeros con la pista: entre agujero y agujero tiene que haber 4 mm de pared."]],
    diff: { mes: "Fer un invent amb dues funcions (un penjador amb safata, un aguantallibres amb porta-llapis) i escriure cinc especificacions. Comprovar-les totes amb el regle de l'app.|Hacer un invento con dos funciones (un colgador con bandeja, un sujetalibros con portalápices) y escribir cinco especificaciones. Comprobarlas todas con la regla de la app.",
      menys: "Triar un dels tres invents dels reptes i canviar-ne només les mides segons la fitxa. Escriure tres especificacions amb frases d'inici.|Elegir uno de los tres inventos de los retos y cambiar solo sus medidas según la ficha. Escribir tres especificaciones con frases de inicio." },
    aval: { ticket: ['Digues una especificació que es pugui comprovar.|Di una especificación que se pueda comprobar.', 'Per què el penjador es dissenya estirat?|¿Por qué el colgador se diseña tumbado?'],
      rubric: [['Especificacions|Especificaciones', "Escriu especificacions comprovables: per a qui, què fa, mides i impressió.|Escribe especificaciones comprobables: para quién, qué hace, medidas e impresión.", 'Escriu idees generals que no es poden comprovar.|Escribe ideas generales que no se pueden comprobar.'],
        ["L'invent|El invento", "El model compleix les especificacions de la fitxa i és una sola peça a la placa.|El modelo cumple las especificaciones de la ficha y es una sola pieza en la placa.", "El model existeix, però no compleix algunes especificacions.|El modelo existe, pero no cumple algunas especificaciones."],
        ['Pensar en la impressió|Pensar en la impresión', "Orienta la peça a la placa perquè no tingui parts a l'aire.|Orienta la pieza en la placa para que no tenga partes en el aire.", "No ha pensat com es col·locarà per imprimir-la.|No ha pensado cómo se colocará para imprimirla."]] },
    casa: "Explica el teu invent a algú de casa amb la fitxa d'especificacions i pregunta-li què milloraria. Apunta-ho: et servirà per a la unitat 8, el teu disseny final.|Explica tu invento a alguien de casa con la ficha de especificaciones y pregúntale qué mejoraría. Apúntalo: te servirá para la unidad 8, tu diseño final.",
    intro: "Projecte de la unitat: l'alumnat recorre sencer el camí del disseny per a un usuari real (l'escola). Les especificacions fan de pont entre les persones i el model, i preparen el projecte final del curs.|Proyecto de la unidad: el alumnado recorre entero el camino del diseño para un usuario real (la escuela). Las especificaciones hacen de puente entre las personas y el modelo, y preparan el proyecto final del curso.",
    claus: ["Les especificacions s'escriuen abans de modelar i es comproven al final.|Las especificaciones se escriben antes de modelar y se comprueban al final.", "Una bona especificació es pot comprovar: amb una mida, una acció o una comprovació de l'app.|Una buena especificación se puede comprobar: con una medida, una acción o una comprobación de la app.",
      'Els invents útils es fan amb les formes de sempre: caixes, falques i forats.|Los inventos útiles se hacen con las formas de siempre: cajas, cuñas y agujeros.', "Pensar com es posarà la peça a la placa la fa més forta i fàcil d'imprimir.|Pensar cómo se pondrá la pieza en la placa la hace más fuerte y fácil de imprimir."],
    prev: ["Haver fet les sessions de la unitat 7 (entrevista, esbós i versions).|Haber hecho las sesiones de la unidad 7 (entrevista, boceto y versiones).", 'Saber girar peces en z de 15 en 15°.|Saber girar piezas en z de 15 en 15°.', 'Saber buidar una caixa amb forats caixa.|Saber vaciar una caja con agujeros caja.'],
    faq: [["Un alumne/a vol fer un invent que no és dels tres. Pot?|Un alumno/a quiere hacer un invento que no es de los tres. ¿Puede?", "És clar: el que importa és que respongui una necessitat de l'escola i que n'escrigui les especificacions abans de modelar-lo.|Claro: lo que importa es que responda a una necesidad de la escuela y que escriba sus especificaciones antes de modelarlo."],
      ['Aguantaria de veritat una motxilla un penjador imprès?|¿Aguantaría de verdad una mochila un colgador impreso?', "Un penjador com el del repte, estirat i de 12 mm de gruix, pot aguantar una motxilla d'escola. Per a pesos grans caldrien més gruix i bons cargols.|Un colgador como el del reto, tumbado y de 12 mm de grosor, puede aguantar una mochila escolar. Para pesos grandes harían falta más grosor y buenos tornillos."],
      ["Com triem quins invents imprimim?|¿Cómo elegimos qué inventos imprimimos?", "Si teniu impressora, podeu imprimir els que compleixin millor les especificacions o fer un vot per a l'invent més útil. Totes les peces dels reptes caben a la placa.|Si tenéis impresora, podéis imprimir los que cumplan mejor las especificaciones o hacer una votación para el invento más útil. Todas las piezas de los retos caben en la placa."]],
    tec: [["La comprovació «S'assembla al fantasma» no es marca a l'aguantallibres.|La comprobación «Se parece al fantasma» no se marca en el sujetalibros.", "Sovint és la falca: cal girar-la 90° a l'eix Z i posar-la a z = 5, sobre la base. Mireu-ho de costat.|A menudo es la cuña: hay que girarla 90° en el eje Z y ponerla en z = 5, sobre la base. Miradlo de lado."],
      ["No es pot desar l'invent: «Cap a la placa de la Nuvi» no es marca.|No se puede guardar el invento: «Cabe en la placa de Nuvi» no se marca.", "L'invent fa més de 180 × 180 × 150 mm. Que el faci més petit: segur que les especificacions no demanen tant.|El invento mide más de 180 × 180 × 150 mm. Que lo haga más pequeño: seguro que las especificaciones no piden tanto."],
      ["Al penjador, els forats per als cargols no es veuen.|En el colgador, los agujeros para los tornillos no se ven.", "Toqueu «Resultat»: a la vista d'edició, els forats són translúcids. Han de ser més alts que el penjador (14 mm).|Tocad «Resultado»: en la vista de edición, los agujeros son translúcidos. Tienen que ser más altos que el colgador (14 mm)."]],
    extra: ["Presentar els invents a la directora o a la bibliotecària i recollir-ne la retroacció.|Presentar los inventos a la directora o a la bibliotecaria y recoger su retroalimentación.", "Fer una exposició «Invents per a l'escola» amb les fitxes d'especificacions i les miniatures.|Hacer una exposición «Inventos para la escuela» con las fichas de especificaciones y las miniaturas.", "Buscar invents de persones joves que van resoldre un problema de la seva escola o del seu barri.|Buscar inventos de personas jóvenes que resolvieron un problema de su escuela o de su barrio."],
    trans: ["Unitat següent: el disseny final del curs, de la idea a la presentació.|Unidad siguiente: el diseño final del curso, de la idea a la presentación.", "Tecnologia: el projecte tecnològic complet (necessitat, especificacions, disseny i avaluació).|Tecnología: el proyecto tecnológico completo (necesidad, especificaciones, diseño y evaluación)."],
    slides: [
      { id: 's1', k: 'portada', t: "Un invent per a l'escola|Un invento para la escuela", x: "El concurs d'invents de la Montse|El concurso de inventos de Montse", nota: "Presenta el projecte de la unitat i el concurs.|Presenta el proyecto de la unidad y el concurso." },
      { id: 's2', k: 'pregunta', t: 'Què necessita la nostra escola?|¿Qué necesita nuestra escuela?', x: 'Penseu en coses que es perden, cauen o estan desordenades.|Pensad en cosas que se pierden, caen o están desordenadas.', nota: "Apunta les idees a la pissarra: poden ser invents dels alumnes.|Apunta las ideas en la pizarra: pueden ser inventos de los alumnos." },
      { id: 's3', k: 'anim', t: 'Les especificacions|Las especificaciones', anim: 'm7spec', x: 'Per a qui · què fa · mides · com s\'imprimeix.|Para quién · qué hace · medidas · cómo se imprime.', nota: "Remarca que s'escriuen abans de modelar.|Remarca que se escriben antes de modelar." },
      { id: 's4', k: 'media', t: 'Tres invents|Tres inventos', x: 'Penjador, aguantallibres i organitzador.|Colgador, sujetalibros y organizador.', media: { k: 'model', model: { parts: INVENTS } }, nota: "Gira el model i demana per a què serveix cada part de cada invent.|Gira el modelo y pide para qué sirve cada parte de cada invento." },
      { id: 's5', k: 'media', t: "Pensat per imprimir|Pensado para imprimir", x: "El penjador, estirat: sense suports i més fort.|El colgador, tumbado: sin soportes y más fuerte.", media: { k: 'model', model: { parts: HOOK(-19) } }, nota: "Pregunta què passaria si l'imprimíssim dret.|Pregunta qué pasaría si lo imprimiéramos de pie." },
      { id: 's6', k: 'anim', t: 'El camí del disseny|El camino del diseño', anim: 'm7road', x: 'Escoltar, esbossar, modelar, provar i millorar.|Escuchar, esbozar, modelar, probar y mejorar.', nota: "Relaciona cada parada amb una sessió de la unitat.|Relaciona cada parada con una sesión de la unidad." },
      { id: 's7', k: 'activitat', t: "La fitxa d'especificacions|La ficha de especificaciones", timer: 8, punts: ['Per a qui és i què fa.|Para quién es y qué hace.', 'Mides: mesura el que hi anirà.|Medidas: mide lo que irá en él.', 'Esbós amb cotes.|Boceto con cotas.'], nota: "Individual. Passa per les taules revisant que les especificacions es puguin comprovar.|Individual. Pasa por las mesas revisando que las especificaciones se puedan comprobar." },
      { id: 's8', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El penjador estirat.|El colgador tumbado.', "L'aguantallibres amb reforços.|El sujetalibros con refuerzos.", "L'organitzador amb tres compartiments.|El organizador con tres compartimentos."], nota: "Aquests tres reptes són models per al seu invent.|Estos tres retos son modelos para su invento." },
      { id: 's9', k: 'media', t: "L'aguantallibres|El sujetalibros", x: 'Falques girades 90° en z, a sobre de la base.|Cuñas giradas 90° en z, encima de la base.', media: { k: 'model', model: { parts: BOOK }, view: 'right' }, nota: "Des del costat es veu el triangle de cada reforç.|Desde el lado se ve el triángulo de cada refuerzo." },
      { id: 's10', k: 'media', t: "L'organitzador|El organizador", x: 'Tres forats caixa amb parets de 3 i 4 mm.|Tres agujeros caja con paredes de 3 y 4 mm.', media: { k: 'model', model: { parts: ORG }, view: 'top' }, nota: "Des de dalt es veuen bé els tres compartiments.|Desde arriba se ven bien los tres compartimentos." },
      { id: 's11', k: 'repte', t: "El teu invent per a l'escola|Tu invento para la escuela", punts: ['Segueix la teva fitxa.|Sigue tu ficha.', 'Comprova cada especificació.|Comprueba cada especificación.', 'Pensa com anirà a la placa.|Piensa cómo irá en la placa.'], nota: "El botó STL permet descarregar-lo si el voleu imprimir.|El botón STL permite descargarlo si lo queréis imprimir." },
      { id: 's12', k: 'concepte', t: 'Abans de desar|Antes de guardar', x: "Repassa la fitxa: cada especificació, comprovada amb el regle de l'app.|Repasa la ficha: cada especificación, comprobada con la regla de la app.", nota: "Que marquin a la fitxa les especificacions que compleixen.|Que marquen en la ficha las especificaciones que cumplen." },
      { id: 's13', k: 'activitat', t: "La galeria d'invents|La galería de inventos", timer: 4, punts: ['Per a qui és?|¿Para quién es?', 'Quina especificació compleix?|¿Qué especificación cumple?', 'Com es posarà a la placa?|¿Cómo se pondrá en la placa?'], nota: "Tres o quatre voluntaris al projector, un minut cadascú.|Tres o cuatro voluntarios en el proyector, un minuto cada uno." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Les especificacions s'escriuen abans de modelar.|Las especificaciones se escriben antes de modelar.", "S'han de poder comprovar.|Se tienen que poder comprobar.", "Pensar la placa també és dissenyar.|Pensar la placa también es diseñar."], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Una especificació que es pugui comprovar.|Una especificación que se pueda comprobar.', 'Per què el penjador va estirat?|¿Por qué el colgador va tumbado?'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Explica el teu invent a casa i apunta què milloraria algú de la família.|Explica tu invento en casa y apunta qué mejoraría alguien de la familia.", nota: 'Proposta opcional: prepara la unitat 8.|Propuesta opcional: prepara la unidad 8.' }
    ],
    print: [{ id: 'p1', t: "Fitxa d'especificacions de l'invent|Ficha de especificaciones del invento", k: 'fitxa', intro: "Omple la fitxa abans de modelar. Al final, marca cada especificació que compleixi el teu model.|Rellena la ficha antes de modelar. Al final, marca cada especificación que cumpla tu modelo.",
      items: [{ q: "El meu invent és: ____ · Per a qui: ____ · On: ____|Mi invento es: ____ · Para quién: ____ · Dónde: ____", sol: "Per exemple: un penjador per als alumnes de 4t, al passadís.|Por ejemplo: un colgador para los alumnos de 4.º, en el pasillo." }, { q: "Què ha de fer (amb verbs): ____|Qué tiene que hacer (con verbos): ____", sol: 'Per exemple: aguantar una motxilla per la nansa.|Por ejemplo: aguantar una mochila por el asa.' },
        { q: "Mides: el que hi anirà fa ____ mm → l'invent farà com a molt ____ × ____ × ____ mm|Medidas: lo que irá en él mide ____ mm → el invento medirá como mucho ____ × ____ × ____ mm", sol: "Mides mesurades amb el regle i una mida màxima que càpiga a la placa.|Medidas medidas con la regla y una medida máxima que quepa en la placa." }, { q: "Per imprimir-lo: com anirà a la placa? Parets de quants mm?|Para imprimirlo: ¿cómo irá en la placa? ¿Paredes de cuántos mm?", sol: "Per exemple: estirat, sense parts a l'aire, parets de 3 mm.|Por ejemplo: tumbado, sin partes en el aire, paredes de 3 mm." },
        { q: "Esbós de davant i de dalt amb les cotes.|Boceto de delante y de arriba con las cotas.", sol: "Dues vistes amb les mides principals.|Dos vistas con las medidas principales." }] }]
  }
  };
})());
